{"path": "zipper.py", "content": "class Zipper:
    """Zipper over binary trees represented as dicts:
    {"value": v, "left": tree_or_None, "right": tree_or_None}.

    The focus is a subtree; breadcrumbs record the path back to the root as
    (direction, parent_value, other_subtree) tuples.
    """

    def __init__(self, focus, crumbs):
        self._focus = focus
        self._crumbs = crumbs

    @staticmethod
    def from_tree(tree):
        return Zipper(tree, ())

    def value(self):
        return self._focus["value"]

    def set_value(self, value):
        return Zipper(dict(self._focus, value=value), self._crumbs)

    def left(self):
        child = self._focus["left"]
        if child is None:
            return None
        crumb = ("left", self._focus["value"], self._focus["right"])
        return Zipper(child, (crumb,) + self._crumbs)

    def set_left(self, tree):
        return Zipper(dict(self._focus, left=tree), self._crumbs)

    def right(self):
        child = self._focus["right"]
        if child is None:
            return None
        crumb = ("right", self._focus["value"], self._focus["left"])
        return Zipper(child, (crumb,) + self._crumbs)

    def set_right(self, tree):
        return Zipper(dict(self._focus, right=tree), self._crumbs)

    def up(self):
        if not self._crumbs:
            return None
        (direction, value, other), rest = self._crumbs[0], self._crumbs[1:]
        if direction == "left":
            parent = {"value": value, "left": self._focus, "right": other}
        else:
            parent = {"value": value, "left": other, "right": self._focus}
        return Zipper(parent, rest)

    def to_tree(self):
        zipper = self
        while True:
            parent = zipper.up()
            if parent is None:
                return zipper._focus
            zipper = parent
